    ($val$Swimming$val$, (SELECT id FROM icons WHERE name = $val$pool-dive$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Agility$val$ LIMIT 1), $val$Proficiency in aquatic movement.$val$),
    ($val$Axes$val$, (SELECT id FROM icons WHERE name = $val$crossed-axes$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Strength$val$ LIMIT 1), $val$Axes of all kinds, also when thrown.$val$),
    ($val$Bows$val$, (SELECT id FROM icons WHERE name = $val$bow-arrow$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Agility$val$ LIMIT 1), $val$Any bow. Crossbows have their own skill.$val$),
    ($val$Brawling$val$, (SELECT id FROM icons WHERE name = $val$high-punch$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Strength$val$ LIMIT 1), $val$Fighting bare-handed, with feet, teeth, or claws too.$val$),
    ($val$Crossbows$val$, (SELECT id FROM icons WHERE name = $val$crossbow$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Agility$val$ LIMIT 1), $val$Every kind of crossbow.$val$),
    ($val$Hammers$val$, (SELECT id FROM icons WHERE name = $val$gavel$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Strength$val$ LIMIT 1), $val$Blunt weapons, warhammers, clubs, flails and maces.$val$),
    ($val$Knives$val$, (SELECT id FROM icons WHERE name = $val$kitchen-knives$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Agility$val$ LIMIT 1), $val$Knives and daggers, in hand or thrown.$val$),
    ($val$Slings$val$, (SELECT id FROM icons WHERE name = $val$sling$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Agility$val$ LIMIT 1), $val$Loosing stones from a sling.$val$),
    ($val$Spears$val$, (SELECT id FROM icons WHERE name = $val$spears$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Strength$val$ LIMIT 1), $val$Spears, lances, halberds and tridents, also when thrown.$val$),
    ($val$Staves$val$, (SELECT id FROM icons WHERE name = $val$wizard-staff$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Agility$val$ LIMIT 1), $val$Staff fighting.$val$),
    ($val$Swords$val$, (SELECT id FROM icons WHERE name = $val$crossed-swords$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Core$val$ LIMIT 1), (SELECT id FROM attributes WHERE name = $val$Strength$val$ LIMIT 1), $val$Every kind of sword.$val$),
    ($val$Adaptive$val$, (SELECT id FROM icons WHERE name = $val$chameleon-glyph$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Substitute any skill you own for the one a roll calls for, if you can explain how it fits. The GM rules on the fit and errs on the side of yes.$val$),
    ($val$Hard To Catch$val$, (SELECT id FROM icons WHERE name = $val$swirl-ring$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Spend it while dodging to give the EVADE roll a boon.$val$),
    ($val$Unforgiving$val$, (SELECT id FROM icons WHERE name = $val$enrage$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Activate when attacking a creature that has dealt you at least 1 point of damage at any time in the past. The attack roll gains a boon.$val$),
    ($val$Inner Peace$val$, (SELECT id FROM icons WHERE name = $val$meditation$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$During a stretch rest you may sink into a deep meditation. You recover an extra D6 HP and an extra D6 WP and shake off one more condition, but nothing can rouse you until the rest ends.$val$),
    ($val$Ill Tempered$val$, (SELECT id FROM icons WHERE name = $val$angry-eyes$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Activate (no action) before any skill roll to gain a boon on it. You also gain the Angry condition if you did not have it already. Not usable on INT rolls or INT-based skills.$val$),
    ($val$Webbed Feet$val$, (SELECT id FROM icons WHERE name = $val$duck-palm$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$SWIMMING rolls gain a boon, and water never slows you down, on the surface or below it.$val$),
    ($val$Hunting Instinct$val$, (SELECT id FROM icons WHERE name = $val$beast-eye$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Mark one creature you can see or smell as your prey; in combat this takes an action. For a full day you can track the prey by scent. Attacks against it gain a boon for a further 1 WP, spent without an action.$val$),
    ($val$Resilient$val$, (SELECT id FROM icons WHERE name = $val$diamond-hard$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Activate for a boon on CON rolls to resist poison or disease (pages 52–53), or to make camp with no BUSHCRAFT roll (page 103). Raw food never makes you sick, at no WP cost.$val$),
    ($val$Body Slam$val$, (SELECT id FROM icons WHERE name = $val$punch-blast$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$An unarmed melee attack made with a boon that cannot be parried. It deals 2D6 bludgeoning damage with no damage bonus, and you may dash first. A humanoid of Normal size or smaller that is hit falls prone.$val$),
    ($val$Tough$val$, (SELECT id FROM icons WHERE name = $val$rock$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$At zero HP, activate to rally at once (page 50) with no WIL roll and no need for another character to PERSUADE you. Meant for player characters and important NPCs.$val$),
    ($val$Nine Lives$val$, (SELECT id FROM icons WHERE name = $val$cat$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Spend 3 WP to activate for a boon on a death roll (page 50). Alternatively, after the ACROBATICS roll to soften a fall (page 53), spend up to 3 WP to remove one D6 of falling damage per WP.$val$),
    ($val$Leaping$val$, (SELECT id FROM icons WHERE name = $val$leapfrog$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Activate to jump your full movement rating forward or half of it upward, with no ACROBATICS roll. If the jump ends next to an enemy, you may follow it with a melee attack made with a boon.$val$),
    ($val$Wings$val$, (SELECT id FROM icons WHERE name = $val$spiky-wing$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Fly at your walking speed for 1 WP each round.$val$),
    ($val$Camouflage$val$, (SELECT id FROM icons WHERE name = $val$hidden$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$Activate for a boon on a SNEAKING roll.$val$),
    ($val$Raise Spirits$val$, (SELECT id FROM icons WHERE name = $val$morbid-humour$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Innate$val$ LIMIT 1), NULL, $val$As an action, sing or recite to remove one condition of your choice from an ally within 10 meters who can hear you. It does not work on yourself.$val$),
    ($val$Assassin$val$, (SELECT id FROM icons WHERE name = $val$hooded-assassin$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Add D8 to the damage of a sneak attack.$val$),
    ($val$Backstabbing$val$, (SELECT id FROM icons WHERE name = $val$backstab$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Melee attack against an enemy close to another player. Your sneak attack cannot be dodged or parried, have a boon and the number of dice rolled for the damage is increased by one.$val$),
    ($val$Battle Cry$val$, (SELECT id FROM icons WHERE name = $val$shouting$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Each other player character within earshot sheds one condition of their choice, right away.$val$),
    ($val$Berserker$val$, (SELECT id FROM icons WHERE name = $val$mighty-force$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$You gain the Angry condition and a boon to melee attacks, but can not parry or dodge. After the fight you become Exhausted.$val$),
    ($val$Catlike$val$, (SELECT id FROM icons WHERE name = $val$cat$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Each WP spent removes one D6 from falling damage.$val$),
    ($val$Companion$val$, (SELECT id FROM icons WHERE name = $val$feline$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Turn one animal (not a monster) into your companion. The animal can scout and also attack for a WP cost of 3.$val$),
    ($val$Contortionist$val$, (SELECT id FROM icons WHERE name = $val$contortionist$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Slip out of bonds or through a tight gap with no skill roll.$val$),
    ($val$Defensive$val$, (SELECT id FROM icons WHERE name = $val$defensive-wall$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Try to Parry an attack without using your action for the round.$val$),
    ($val$Deflect Arrow$val$, (SELECT id FROM icons WHERE name = $val$shield-reflect$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$A melee weapon can parry arrows, bolts, and other ranged attacks.$val$),
    ($val$Disguise$val$, (SELECT id FROM icons WHERE name = $val$prank-glasses$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Pass yourself off as a specific other person, in face, voice, and manner.$val$),
    ($val$Double Slash$val$, (SELECT id FROM icons WHERE name = $val$crossed-slashes$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$One swing hits two enemies within 2 meters.$val$),
    ($val$Dragon Slayer$val$, (SELECT id FROM icons WHERE name = $val$dragon-head$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Add D8 damage to an attack on a monster.$val$),
    ($val$Dual Wield$val$, (SELECT id FROM icons WHERE name = $val$rogue$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Make a second attack with your off-hand weapon, with a bane.$val$),
    ($val$Eagle Eye$val$, (SELECT id FROM icons WHERE name = $val$eagle-head$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$For one stretch, make out people and objects up to 200 meters away, and shoot past your weapon's range with no bane.$val$),
    ($val$Fast Footwork$val$, (SELECT id FROM icons WHERE name = $val$foot-trip$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Try to Dodge an attack without using your action for the round.$val$),
    ($val$Fast Healer$val$, (SELECT id FROM icons WHERE name = $val$health-increase$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$A stretch rest restores an extra D6 HP.$val$),
    ($val$Fearless$val$, (SELECT id FROM icons WHERE name = $val$lion$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Fear never takes hold; no WIL roll is needed.$val$),
    ($val$Focused$val$, (SELECT id FROM icons WHERE name = $val$rear-aura$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Maximum WP rises by 2 for good.$val$),
    ($val$Guardian$val$, (SELECT id FROM icons WHERE name = $val$guarded-tower$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Draw an enemy's attack onto yourself instead of a nearby ally.$val$),
    ($val$Insight$val$, (SELECT id FROM icons WHERE name = $val$inspiration$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$An AWARENESS roll tells you whether someone is lying, though not what about.$val$),
    ($val$Intuition$val$, (SELECT id FROM icons WHERE name = $val$idea$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Put one question to the GM and get a useful answer.$val$),
    ($val$Iron Fist$val$, (SELECT id FROM icons WHERE name = $val$fist$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Unarmed attacks deal 2D6 damage.$val$),
    ($val$Iron Grip$val$, (SELECT id FROM icons WHERE name = $val$grab$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Grappling BRAWLING rolls gain a boon.$val$),
    ($val$Lightning Fast$val$, (SELECT id FROM icons WHERE name = $val$running-ninja$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Draw two initiative cards and keep the one you prefer.$val$),
    ($val$Lone Wolf$val$, (SELECT id FROM icons WHERE name = $val$wolf-howl$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Take a shift rest without a roll for BUSHCRAFT.$val$),
    ($val$Magic Talent$val$, (SELECT id FROM icons WHERE name = $val$embrassed-energy$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Learn one more school of magic.$val$),
    ($val$Massive Blow$val$, (SELECT id FROM icons WHERE name = $val$corner-explosion$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$A two-handed melee weapon strike adds D* damage, but you cannot move that round.$val$),
    ($val$Master Blacksmith$val$, (SELECT id FROM icons WHERE name = $val$blacksmith$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Sharpen weapons and craft metal weapons and armor.$val$),
    ($val$Master Carpenter$val$, (SELECT id FROM icons WHERE name = $val$hand-saw$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Do D12 damage to objects and craft wood weapons and tools.$val$),
    ($val$Master Chef$val$, (SELECT id FROM icons WHERE name = $val$chef-toque$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Cooking always succeeds, with no BUSHCRAFT roll.$val$),
    ($val$Master SpellCaster$val$, (SELECT id FROM icons WHERE name = $val$pointy-hat$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Cast two spells with one action, as long as they are different spells.$val$),
    ($val$Master Tanner$val$, (SELECT id FROM icons WHERE name = $val$animal-hide$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Craft leather armor from animals and monsters.$val$),
    ($val$Master Hunter$val$, (SELECT id FROM icons WHERE name = $val$hunting-horn$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$At a fork in the road, learn which way the most dangerous enemies lie.$val$),
    ($val$Musician$val$, (SELECT id FROM icons WHERE name = $val$musical-notes$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Allies within 10 meters gain a boon on every roll, or enemies in that range take a bane, for one turn.$val$),
    ($val$Pathfinder$val$, (SELECT id FROM icons WHERE name = $val$trail$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$BUSHCRAFT rolls to find your way in the wild gain a boon.$val$),
    ($val$Quartermaster$val$, (SELECT id FROM icons WHERE name = $val$barracks-tent$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Making camp on a journey always succeeds.$val$),
    ($val$Robust$val$, (SELECT id FROM icons WHERE name = $val$muscle-fat$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Maximum HP rises by 2.$val$),
    ($val$Sea Legs$val$, (SELECT id FROM icons WHERE name = $val$wave-surfer$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$You are safe from all negative effects of being in water for one round, including the risk of drowning.$val$),
    ($val$Shield Block$val$, (SELECT id FROM icons WHERE name = $val$roman-shield$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Shield parries gain a boon, and a shield can parry a monster's physical attacks that no weapon could, area effects excepted.$val$),
    ($val$Throwing Arm$val$, (SELECT id FROM icons WHERE name = $val$throwing-ball$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Throw a melee weapon at an enemy within your STR meters. It must be a onehanded weapon.$val$),
    ($val$Treasure Hunter$val$, (SELECT id FROM icons WHERE name = $val$treasure-map$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$At a fork in the road, learn which way the richest treasure lies.$val$),
    ($val$Twin Shot$val$, (SELECT id FROM icons WHERE name = $val$double-shot$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Loose two arrows from a bow, not a crossbow, with one attack roll made with a bane.$val$),
    ($val$Veteran$val$, (SELECT id FROM icons WHERE name = $val$wisdom$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$Keep last round's initiative card.$val$),
    ($val$Weasel$val$, (SELECT id FROM icons WHERE name = $val$two-shadows$val$ LIMIT 1), (SELECT id FROM skill_kinds WHERE name = $val$Heroic$val$ LIMIT 1), NULL, $val$If attacked and another player is within 2 meters, you can let the attack hit that player instead of you.$val$);
